insert into public.articles (slug, judul, kategori, tanggal, penulis, tags, featured, excerpt, cover_url, caption, konten) values
  ('analisis-kritis-kebijakan-ukt-baru', 'Analisis Kritis Kebijakan UKT Baru: Menuju Pendidikan yang Terjangkau?', 'kajian-strategis', '2026-03-15', 'Departemen Kastrat', array['UKT', 'Advokasi']::text[], true, 'Pemaparan komprehensif mengenai dampak struktur Uang Kuliah Tunggal terbaru terhadap aksesibilitas mahasiswa baru dan keluarganya.', '/images/news/analisis-kritis-kebijakan-ukt-baru.jpg', 'Suasana kampus UI Depok.', '[{"type": "p", "text": "Pemaparan komprehensif mengenai dampak struktur Uang Kuliah Tunggal terbaru terhadap aksesibilitas mahasiswa baru dan keluarganya."}, {"type": "h2", "text": "Latar belakang"}, {"type": "p", "text": "Struktur UKT 2026 menambah dua golongan baru di atas golongan tertinggi sebelumnya. Kajian ini membaca data penetapan golongan mahasiswa baru dan membandingkannya dengan kemampuan bayar yang dilaporkan."}, {"type": "quote", "text": "Mahasiswa berhak tahu, dan berhak didengar.", "cite": "Perwakilan mahasiswa"}, {"type": "h2", "text": "Poin penting"}, {"type": "ul", "items": ["Golongan baru membuat selisih antar-golongan semakin lebar.", "Proses banding UKT belum punya tenggat jawaban yang jelas.", "Data pendapatan keluarga belum diverifikasi ulang setelah penetapan."]}, {"type": "p", "text": "BEM UI akan terus mengawal isu ini dan memperbarui informasinya di kanal resmi. Punya data atau pengalaman terkait? Sampaikan melalui media sosial resmi BEM UI."}]'::jsonb),
  ('pernyataan-sikap-isu-lingkungan-kampus', 'Pernyataan Sikap BEM UI Terkait Isu Lingkungan Kampus', 'siaran-pers', '2026-03-12', 'Departemen Adkesma', array['FasilitasKampus']::text[], false, 'BEM UI menyampaikan sikap resmi atas rencana alih fungsi ruang terbuka hijau di area kampus Depok.', '/images/news/pernyataan-sikap-isu-lingkungan-kampus.jpg', 'Suasana kampus UI Depok.', '[{"type": "p", "text": "BEM UI menyampaikan sikap resmi atas rencana alih fungsi ruang terbuka hijau di area kampus Depok."}, {"type": "h2", "text": "Latar belakang"}, {"type": "p", "text": "Rencana pembangunan di area ruang terbuka hijau disampaikan tanpa konsultasi publik dengan mahasiswa. BEM UI meminta proses ini dibuka."}, {"type": "quote", "text": "Mahasiswa berhak tahu, dan berhak didengar.", "cite": "Perwakilan mahasiswa"}, {"type": "h2", "text": "Poin penting"}, {"type": "ul", "items": ["Membuka dokumen rencana pembangunan kepada publik.", "Mengadakan konsultasi terbuka dengan mahasiswa.", "Menjamin luas ruang terbuka hijau tidak berkurang."]}, {"type": "p", "text": "BEM UI akan terus mengawal isu ini dan memperbarui informasinya di kanal resmi. Punya data atau pengalaman terkait? Sampaikan melalui media sosial resmi BEM UI."}]'::jsonb),
  ('evaluasi-transportasi-internal-ui', 'Evaluasi Kinerja Fasilitas Transportasi Internal UI Semester Ganjil', 'kabar-ui', '2026-03-10', 'Biro Multimedia', array['TransportasiUI', 'FasilitasKampus']::text[], false, 'Hasil survei terhadap 1.200 pengguna bis kuning menunjukkan waktu tunggu yang masih panjang di jam sibuk.', '/images/news/evaluasi-transportasi-internal-ui.jpg', 'Suasana kampus UI Depok.', '[{"type": "p", "text": "Hasil survei terhadap 1.200 pengguna bis kuning menunjukkan waktu tunggu yang masih panjang di jam sibuk."}, {"type": "h2", "text": "Latar belakang"}, {"type": "p", "text": "Survei dilakukan selama tiga minggu di seluruh halte kampus Depok. Responden diminta mencatat waktu tunggu, kepadatan, dan ketepatan jadwal."}, {"type": "quote", "text": "Mahasiswa berhak tahu, dan berhak didengar.", "cite": "Perwakilan mahasiswa"}, {"type": "h2", "text": "Poin penting"}, {"type": "ul", "items": ["Waktu tunggu jam sibuk rata-rata lebih dari 15 menit.", "Rute melingkar arah fakultas teknik paling padat.", "Responden meminta jadwal real-time di aplikasi."]}, {"type": "p", "text": "BEM UI akan terus mengawal isu ini dan memperbarui informasinya di kanal resmi. Punya data atau pengalaman terkait? Sampaikan melalui media sosial resmi BEM UI."}]'::jsonb),
  ('urgensi-ruang-aman-lingkungan-akademik', 'Urgensi Ruang Aman di Lingkungan Akademik', 'opini', '2026-03-08', 'Redaksi BEM UI', array['KekerasanSeksual', 'Advokasi']::text[], false, 'Ruang aman bukan fasilitas tambahan. Ia syarat dasar agar semua mahasiswa bisa belajar tanpa rasa takut.', '/images/news/urgensi-ruang-aman-lingkungan-akademik.jpg', 'Suasana kampus UI Depok.', '[{"type": "p", "text": "Ruang aman bukan fasilitas tambahan. Ia syarat dasar agar semua mahasiswa bisa belajar tanpa rasa takut."}, {"type": "h2", "text": "Latar belakang"}, {"type": "p", "text": "Kampus yang aman dimulai dari mekanisme pelaporan yang dipercaya. Tanpa itu, kasus akan terus terkubur."}, {"type": "quote", "text": "Mahasiswa berhak tahu, dan berhak didengar.", "cite": "Perwakilan mahasiswa"}, {"type": "h2", "text": "Poin penting"}, {"type": "ul", "items": ["Kanal pelaporan harus bisa diakses tanpa takut identitas bocor.", "Pendampingan korban perlu tenaga profesional.", "Sanksi harus ditegakkan secara konsisten."]}, {"type": "p", "text": "BEM UI akan terus mengawal isu ini dan memperbarui informasinya di kanal resmi. Punya data atau pengalaman terkait? Sampaikan melalui media sosial resmi BEM UI."}]'::jsonb),
  ('dampak-digitalisasi-birokrasi-kemahasiswaan', 'Dampak Digitalisasi Birokrasi Kemahasiswaan', 'kajian-strategis', '2026-03-05', 'Departemen Kastrat', array['FasilitasKampus']::text[], false, 'Digitalisasi layanan mempercepat sebagian urusan, tetapi juga menciptakan hambatan baru bagi sebagian mahasiswa.', '/images/news/dampak-digitalisasi-birokrasi-kemahasiswaan.jpg', 'Suasana kampus UI Depok.', '[{"type": "p", "text": "Digitalisasi layanan mempercepat sebagian urusan, tetapi juga menciptakan hambatan baru bagi sebagian mahasiswa."}, {"type": "h2", "text": "Latar belakang"}, {"type": "p", "text": "Kajian ini memetakan sepuluh layanan kemahasiswaan yang dipindahkan ke sistem daring dalam dua tahun terakhir."}, {"type": "quote", "text": "Mahasiswa berhak tahu, dan berhak didengar.", "cite": "Perwakilan mahasiswa"}, {"type": "h2", "text": "Poin penting"}, {"type": "ul", "items": ["Layanan surat keterangan jauh lebih cepat.", "Integrasi antar-sistem masih lemah.", "Belum ada kanal bantuan bagi mahasiswa yang terkendala akses."]}, {"type": "p", "text": "BEM UI akan terus mengawal isu ini dan memperbarui informasinya di kanal resmi. Punya data atau pengalaman terkait? Sampaikan melalui media sosial resmi BEM UI."}]'::jsonb),
  ('pembaruan-layanan-kesehatan-mahasiswa', 'Pembaruan Layanan Kesehatan Mahasiswa di Klinik Satelit', 'kabar-ui', '2026-03-01', 'Departemen Adkesma', array['KesehatanMahasiswa']::text[], false, 'Klinik Satelit UI kini membuka layanan konsultasi hingga malam hari pada hari kerja.', '/images/news/pembaruan-layanan-kesehatan-mahasiswa.jpg', 'Suasana kampus UI Depok.', '[{"type": "p", "text": "Klinik Satelit UI kini membuka layanan konsultasi hingga malam hari pada hari kerja."}, {"type": "h2", "text": "Latar belakang"}, {"type": "p", "text": "Perubahan jam layanan ini merupakan hasil audiensi BEM UI dengan pengelola klinik pada awal semester."}, {"type": "quote", "text": "Mahasiswa berhak tahu, dan berhak didengar.", "cite": "Perwakilan mahasiswa"}, {"type": "h2", "text": "Poin penting"}, {"type": "ul", "items": ["Layanan dibuka sampai pukul 20.00 pada hari kerja.", "Pendaftaran bisa dilakukan secara daring.", "Mahasiswa cukup membawa kartu mahasiswa."]}, {"type": "p", "text": "BEM UI akan terus mengawal isu ini dan memperbarui informasinya di kanal resmi. Punya data atau pengalaman terkait? Sampaikan melalui media sosial resmi BEM UI."}]'::jsonb),
  ('hasil-audiensi-direktorat-kemahasiswaan', 'Hasil Audiensi dengan Direktorat Kemahasiswaan', 'siaran-pers', '2026-02-28', 'Biro Multimedia', array['UKT', 'BeasiswaUI']::text[], false, 'BEM UI menyampaikan tiga tuntutan mahasiswa dalam audiensi bersama Direktorat Kemahasiswaan.', '/images/news/hasil-audiensi-direktorat-kemahasiswaan.jpg', 'Suasana kampus UI Depok.', '[{"type": "p", "text": "BEM UI menyampaikan tiga tuntutan mahasiswa dalam audiensi bersama Direktorat Kemahasiswaan."}, {"type": "h2", "text": "Latar belakang"}, {"type": "p", "text": "Audiensi berlangsung selama dua jam dan dihadiri perwakilan BEM dari seluruh fakultas."}, {"type": "quote", "text": "Mahasiswa berhak tahu, dan berhak didengar.", "cite": "Perwakilan mahasiswa"}, {"type": "h2", "text": "Poin penting"}, {"type": "ul", "items": ["Kepastian tenggat jawaban banding UKT.", "Perluasan kuota beasiswa internal.", "Laporan berkala pemanfaatan dana kemahasiswaan."]}, {"type": "p", "text": "BEM UI akan terus mengawal isu ini dan memperbarui informasinya di kanal resmi. Punya data atau pengalaman terkait? Sampaikan melalui media sosial resmi BEM UI."}]'::jsonb),
  ('sosialisasi-aturan-baru-ukt-semester-depan', 'Sosialisasi Aturan Baru UKT Semester Depan', 'kabar-ui', '2026-02-20', 'Redaksi BEM UI', array['UKT']::text[], false, 'Ringkasan aturan UKT yang berlaku mulai semester depan dan apa yang perlu disiapkan mahasiswa.', '/images/news/sosialisasi-aturan-baru-ukt-semester-depan.jpg', 'Suasana kampus UI Depok.', '[{"type": "p", "text": "Ringkasan aturan UKT yang berlaku mulai semester depan dan apa yang perlu disiapkan mahasiswa."}, {"type": "h2", "text": "Latar belakang"}, {"type": "p", "text": "Rektorat menerbitkan peraturan baru mengenai penyesuaian UKT. BEM UI merangkum poin-poin pentingnya."}, {"type": "quote", "text": "Mahasiswa berhak tahu, dan berhak didengar.", "cite": "Perwakilan mahasiswa"}, {"type": "h2", "text": "Poin penting"}, {"type": "ul", "items": ["Pengajuan penyesuaian dibuka empat minggu sebelum pembayaran.", "Dokumen pendukung diunggah lewat SIAK.", "Hasil diumumkan paling lambat dua minggu setelah pengajuan."]}, {"type": "p", "text": "BEM UI akan terus mengawal isu ini dan memperbarui informasinya di kanal resmi. Punya data atau pengalaman terkait? Sampaikan melalui media sosial resmi BEM UI."}]'::jsonb),
  ('evaluasi-program-beasiswa-bem-ui', 'Evaluasi Program Beasiswa BEM UI 2025', 'kajian-strategis', '2026-02-14', 'Departemen Kastrat', array['BeasiswaUI', 'Advokasi']::text[], false, 'Evaluasi penyaluran beasiswa periode lalu sebagai dasar perbaikan program tahun ini.', '/images/news/evaluasi-program-beasiswa-bem-ui.jpg', 'Suasana kampus UI Depok.', '[{"type": "p", "text": "Evaluasi penyaluran beasiswa periode lalu sebagai dasar perbaikan program tahun ini."}, {"type": "h2", "text": "Latar belakang"}, {"type": "p", "text": "Data penerima dan survei kepuasan dikumpulkan dari seluruh penerima beasiswa periode 2025."}, {"type": "quote", "text": "Mahasiswa berhak tahu, dan berhak didengar.", "cite": "Perwakilan mahasiswa"}, {"type": "h2", "text": "Poin penting"}, {"type": "ul", "items": ["Proses seleksi dinilai transparan oleh mayoritas penerima.", "Pencairan dana sering terlambat.", "Perlu pendampingan akademik bagi penerima."]}, {"type": "p", "text": "BEM UI akan terus mengawal isu ini dan memperbarui informasinya di kanal resmi. Punya data atau pengalaman terkait? Sampaikan melalui media sosial resmi BEM UI."}]'::jsonb),
  ('pentingnya-ruang-terbuka-hijau-fakultas', 'Pentingnya Ruang Terbuka Hijau di Area Fakultas', 'opini', '2026-02-10', 'Departemen Adkesma', array['FasilitasKampus']::text[], false, 'Ruang terbuka hijau adalah ruang belajar, ruang istirahat, dan ruang bertemu. Kampus membutuhkan lebih banyak, bukan lebih sedikit.', '/images/news/pentingnya-ruang-terbuka-hijau-fakultas.jpg', 'Suasana kampus UI Depok.', '[{"type": "p", "text": "Ruang terbuka hijau adalah ruang belajar, ruang istirahat, dan ruang bertemu. Kampus membutuhkan lebih banyak, bukan lebih sedikit."}, {"type": "h2", "text": "Latar belakang"}, {"type": "p", "text": "Setiap fakultas punya cerita tentang taman yang berubah jadi parkiran. Tulisan ini mengajak kita menghitung ulang apa yang hilang."}, {"type": "quote", "text": "Mahasiswa berhak tahu, dan berhak didengar.", "cite": "Perwakilan mahasiswa"}, {"type": "h2", "text": "Poin penting"}, {"type": "ul", "items": ["Ruang hijau menurunkan suhu di sekitar gedung kuliah.", "Mahasiswa butuh ruang istirahat di luar kelas.", "Perencanaan kampus perlu melibatkan mahasiswa."]}, {"type": "p", "text": "BEM UI akan terus mengawal isu ini dan memperbarui informasinya di kanal resmi. Punya data atau pengalaman terkait? Sampaikan melalui media sosial resmi BEM UI."}]'::jsonb),
  ('pemira-2026-jadwal-dan-cara-memilih', 'Pemira 2026: Jadwal dan Cara Memilih', 'kabar-ui', '2026-02-05', 'Biro Multimedia', array['Pemira']::text[], false, 'Semua yang perlu kamu tahu tentang Pemilihan Raya IKM UI 2026.', '/images/news/pemira-2026-jadwal-dan-cara-memilih.jpg', 'Suasana kampus UI Depok.', '[{"type": "p", "text": "Semua yang perlu kamu tahu tentang Pemilihan Raya IKM UI 2026."}, {"type": "h2", "text": "Latar belakang"}, {"type": "p", "text": "Pemira adalah cara mahasiswa UI memilih pemimpin lembaganya. Berikut jadwal dan tata cara memilih."}, {"type": "quote", "text": "Mahasiswa berhak tahu, dan berhak didengar.", "cite": "Perwakilan mahasiswa"}, {"type": "h2", "text": "Poin penting"}, {"type": "ul", "items": ["Pemungutan suara dilakukan secara daring.", "Gunakan akun SSO UI untuk masuk.", "Hasil diumumkan setelah rekapitulasi selesai."]}, {"type": "p", "text": "BEM UI akan terus mengawal isu ini dan memperbarui informasinya di kanal resmi. Punya data atau pengalaman terkait? Sampaikan melalui media sosial resmi BEM UI."}]'::jsonb),
  ('refleksi-satu-bulan-kabinet-terusterang', 'Refleksi Satu Bulan Kabinet TerusTerang', 'opini', '2026-01-30', 'Redaksi BEM UI', array['Advokasi']::text[], false, 'Satu bulan pertama: apa yang sudah dikerjakan, apa yang belum, dan apa yang kami pelajari.', '/images/news/refleksi-satu-bulan-kabinet-terusterang.jpg', 'Suasana kampus UI Depok.', '[{"type": "p", "text": "Satu bulan pertama: apa yang sudah dikerjakan, apa yang belum, dan apa yang kami pelajari."}, {"type": "h2", "text": "Latar belakang"}, {"type": "p", "text": "Kami berjanji untuk terus terang. Tulisan ini adalah laporan pertama dari janji itu."}, {"type": "quote", "text": "Mahasiswa berhak tahu, dan berhak didengar.", "cite": "Perwakilan mahasiswa"}, {"type": "h2", "text": "Poin penting"}, {"type": "ul", "items": ["Seluruh divisi sudah menyelesaikan rencana kerja.", "Dua audiensi sudah dilaksanakan.", "Laporan keuangan pertama terbit bulan depan."]}, {"type": "p", "text": "BEM UI akan terus mengawal isu ini dan memperbarui informasinya di kanal resmi. Punya data atau pengalaman terkait? Sampaikan melalui media sosial resmi BEM UI."}]'::jsonb)
